-- JSON payloads and all legacy credentials are intentionally unavailable to the Data API.
alter table app_private.portal_users enable row level security;
alter table app_private.portal_version enable row level security;
alter table app_private.legacy_otp enable row level security;
alter table app_private.document_versions enable row level security;
alter table app_private.source_archives enable row level security;
alter table app_private.import_runs enable row level security;

create table app_private.auth_provisioning (id uuid primary key,phone text not null,payload jsonb not null,status text not null default 'pending' check(status in ('pending','linked')),created_at timestamptz not null default now());
create index auth_provisioning_phone on app_private.auth_provisioning(phone) where status='pending';
alter table app_private.auth_provisioning enable row level security;
